<script setup>
import {computed} from 'vue';
import LinkPreviewCard from './LinkPreviewCard.vue';
import ChatIcon from './ChatIcon.vue';
const props=defineProps({message:Object,mine:Boolean,tail:Boolean});
defineEmits(['react','forward','retry','image']);
const time=computed(()=>new Date(props.message.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}));
const tick=computed(()=>props.message.status==='sending'?'◷':props.message.status==='failed'?'!':props.message.read_at?'✓✓':'✓');
</script>
<template><div class="message-row" :class="{mine,reaction:message.reactions?.length}"><div class="bubble" :class="{tail}"><LinkPreviewCard v-if="message.link_url" :url="message.link_url" :meta="message.link_meta"/><button v-if="message.imageUrl" class="shared-image" @click="$emit('image',message.imageUrl)"><img :src="message.imageUrl" alt="Shared photo" loading="lazy"></button><div v-if="message.body" class="message-body">{{ message.body }}</div><div class="stamp"><button v-if="message.status==='failed'" class="retry" @click="$emit('retry',message)">Retry</button><time :datetime="message.created_at">{{ time }}</time><span v-if="mine" :class="{read:message.read_at}" :aria-label="message.read_at?'Read':message.status||'Sent'">{{ tick }}</span></div><button v-if="message.reactions?.length" class="reaction-pill" :aria-label="'Reacted '+message.reactions.map(r=>r.emoji).join(' ')" @click="$emit('react',message)">{{ [...new Set(message.reactions.map(r=>r.emoji))].join(' ') }}<small v-if="message.reactions.length>1">{{ message.reactions.length }}</small></button></div><div class="message-actions"><button v-if="message.link_url" class="forward" aria-label="Share link" @click="$emit('forward',message)"><ChatIcon name="forward"/></button><button v-if="!['sending','failed'].includes(message.status)" class="add-reaction" aria-label="Toggle thumbs up reaction" @click="$emit('react',message)"></button></div></div></template>
<style scoped>
.message-row{display:flex;align-items:center;gap:8px;margin:3px 0;max-width:100%;padding:0 5px}.message-row.mine{flex-direction:row-reverse}.bubble{position:relative;max-width:82%;min-width:80px;background:#202c33;color:#e9edef;border-radius:12px;padding:7px 9px 5px;}.mine .bubble{background:#005c4b}.bubble.tail:before{content:'';position:absolute;left:-5px;bottom:0;border:6px solid transparent;border-bottom-color:#202c33}.mine .bubble.tail:before{left:auto;right:-5px;border-bottom-color:#005c4b}.message-body{font-size:15px;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere}.stamp{display:flex;justify-content:flex-end;align-items:center;gap:5px;font-size:10px;color:#a7b6bc;margin:2px 0 0 14px}.stamp span{font-size:13px;letter-spacing:0;padding-right:3px}.stamp .read{color:#53bdeb}.reaction{margin-bottom:23px}.reaction-pill{position:absolute;bottom:-20px;left:5px;display:flex;gap:4px;align-items:center;border:2px solid #0b141a;border-radius:12px;background:#202c33;padding:2px 7px;cursor:pointer}.mine .reaction-pill{left:auto;right:5px}.reaction-pill small{color:#aebac1}.message-actions{display:grid;gap:5px;flex:none}.message-actions button{border:0;color:#aebac1;background:#202c33;border-radius:12px;width:30px;height:30px;display:grid;place-items:center;cursor:pointer}.message-actions .add-reaction{opacity:0;background:transparent}.message-row:hover .add-reaction,.message-row:focus-within .add-reaction{opacity:1}.message-actions svg{width:16px;height:16px}.shared-image{display:block;padding:0;border:0;background:none;cursor:zoom-in}.shared-image img{max-height:260px;width:100%;object-fit:contain;border-radius:12px}.retry{background:none;border:0;color:#ffb4a9;text-decoration:underline;cursor:pointer}@media(hover:none){.message-actions .add-reaction{opacity:.65}}
</style>

<style scoped>.bubble{border-radius:12px;box-shadow:0 1px 1px #0002}.stamp span{letter-spacing:-3px}.reaction-pill{border-radius:20px}.message-actions button{border-radius:50%}.shared-image img{border-radius:7px}</style>